pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(c), 1 ether);

        address owner = address(this);

        bool ok;
        vm.prank(caller);
        try c.sendTo(address(0x1234), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == owner && amount > 0));
    }
}
